function frame(payload, opcode = 1) {
  const n = payload.length;
  let h = n < 126 ? Buffer.from([0x80 | opcode, n]) : n <= 65535 ? Buffer.alloc(4) : Buffer.alloc(10);
  if (n >= 126 && n <= 65535) { h[0]=0x80|opcode;h[1]=126;h.writeUInt16BE(n,2); }
  if (n > 65535) { h[0]=0x80|opcode;h[1]=127;h.writeBigUInt64BE(BigInt(n),2); }
  return Buffer.concat([h,payload]);
}
