function cleanup(c,{reconnect=true,notice=`${c.name} left`}={}){if(c.cleaned)return;c.cleaned=true;const a=c.arena;if(!a)return;if(c.role==="player"&&a.players.get(c.slot)===c){a.players.delete(c.slot);if(reconnect)reconnects.set(c.id,{arena:a.id,slot:c.slot,expires:now()+MODE.RECONNECT_MS});else reconnects.delete(c.id);park(a,c.slot);}else a.spectators.delete(c);a.lastUsed=now();broadcast(a,{t:"roster",names:[...a.players].map(([slot,x])=>[slot,x.name]),spaces:openSlots(a).length});broadcast(a,{t:"system",text:notice});broadcastBalance(a);}
function upgrade(req,socket){if(req.headers.upgrade?.toLowerCase()!=="websocket")return socket.destroy();const key=req.headers["sec-websocket-key"],accept=crypto.createHash("sha1").update(key+"258EAFA5-E914-47DA-95CA-C5AB0DC85B11").digest("base64");socket.write(`HTTP/1.1 101 Switching Protocols\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Accept: ${accept}\r\n\r\n`);const c={socket,pending:Buffer.alloc(0),cleaned:false};if(!join(c,parseUrl(req)))return setTimeout(()=>socket.end(),100);socket.on("data",chunk=>{try{for(const f of frames(c,chunk)){if(f.op===8){cleanup(c);socket.end(frame(Buffer.alloc(0),8));return;}if(f.op===9){socket.write(frame(f.p,10));continue;}if(f.op===1)message(c,JSON.parse(f.p.toString("utf8")));}}catch{socket.destroy();}});socket.on("close",()=>cleanup(c));socket.on("error",()=>cleanup(c));}

const server=http.createServer((req,res)=>{res.setHeader("Access-Control-Allow-Origin","*");res.setHeader("Content-Type","application/json");if(req.url==="/health")return res.end(JSON.stringify({ok:true,mode:MODE.ID,arenas:arenas.size,players:[...arenas.values()].reduce((n,a)=>n+a.players.size,0)}));const arena=[...arenas.values()][0];if(process.env.NC11_TESTING==="1"&&arena&&req.url==="/test/setup-corner"){const slots=[...arena.players.keys()];for(const [index,slot] of slots.slice(0,2).entries()){const p=arena.world.players[slot];p.body.setTransform(new planck.Vec2(24+index*2,75),0);p.body.setLinearVelocity(new planck.Vec2());p.input={x:0,y:0,boost:false,brake:false};}arena.world.ball.setTransform(new planck.Vec2(25.5,70),0);arena.world.ball.setLinearVelocity(new planck.Vec2());return res.end(JSON.stringify({ok:true}));}if(process.env.NC11_TESTING==="1"&&arena&&req.url==="/test/setup-wall"){const slots=[...arena.players.keys()];for(const [index,slot] of slots.slice(0,2).entries()){const p=arena.world.players[slot];p.body.setTransform(new planck.Vec2(71.5+index*7,9.5),0);p.body.setLinearVelocity(new planck.Vec2());p.input={x:0,y:0,boost:false,brake:false};}arena.world.ball.setTransform(new planck.Vec2(75,3.5),0);arena.world.ball.setLinearVelocity(new planck.Vec2());return res.end(JSON.stringify({ok:true}));}if(process.env.NC11_TESTING==="1"&&arena&&req.url==="/test/setup-goal"){arena.setPiece=null;broadcast(arena,{t:"restart",active:false});const scorer=[...arena.players.keys()].find(slot=>slot%2===0)??null;arena.lastBallTouchSlot=scorer;arena.ballTouches[0]=scorer;arena.touchHistory=scorer==null?[]:[{slot:scorer,speed:8,tick:arena.world.tick}];arena.ballTouchHistory[0]=arena.touchHistory;arena.world.ball.setTransform(new planck.Vec2(137,MODE.FIELD_HEIGHT/2),0);arena.world.ball.setLinearVelocity(new planck.Vec2(8,0));return res.end(JSON.stringify({ok:true}));}res.statusCode=404;res.end(JSON.stringify({error:"not found"}));});server.on("upgrade",upgrade);
