let physicsLast=performance.now(),physicsAccumulator=0;
function publishSnapshots(){const n=now();for(const a of arenas.values())if(a.players.size||a.spectators.size){enforceDefensiveFifths(a);enforceGoalKickClearance(a);finishSetPieceAfterStep(a);const s=snapshot(a);broadcast(a,s);const recordable=a.phase==="playing"||a.phase==="penaltyCountdown"||a.phase==="penalty"||a.phase==="penaltyPause";if(recordable){a.lastReplayAt=n;const r=a.setPiece;a.replay.push({...s,replayMs:Math.max(0,n-a.startedAt),restart:r?{active:true,type:r.type,team:r.team,x:r.x,y:r.y,ballIndex:r.ballIndex,radius:MODE.CORNER_RADIUS,taker:r.taker}:null,rules:publicRules(a)});}}}
function playRandomEvent(a){if(!a.meowEnabled){a.randomEventPlayed=true;return;}const candidates=[...a.players.values()];if(!candidates.length)return;const first=candidates.splice(Math.floor(Math.random()*candidates.length),1)[0],selected=[first];if(candidates.length&&Math.random()<.5)selected.push(candidates[Math.floor(Math.random()*candidates.length)]);for(const c of selected)send(c,{t:"randomEvent",durationMs:1000});a.events.push({at:a.world.tick,replayMs:Math.max(0,now()-a.startedAt),type:"meow",slots:selected.map(c=>c.slot),durationMs:1000});a.randomEventPlayed=true;}
const physicsTimer=setInterval(()=>{const clock=performance.now(),elapsed=Math.max(0,clock-physicsLast);physicsLast=clock;physicsAccumulator=Math.min(physicsAccumulator+elapsed,PHYSICS_STEP_MS*MODE.MAX_PHYSICS_CATCHUP_STEPS);let stepped=false;while(physicsAccumulator>=PHYSICS_STEP_MS){for(const a of arenas.values())step(a);physicsAccumulator-=PHYSICS_STEP_MS;stepped=true;}if(stepped)publishSnapshots();const n=now();for(const a of arenas.values()){for(const c of [...a.players.values(),...a.spectators])if(n-c.last>MODE.IDLE_MS)c.socket.end();const inactivityMs=MODE.INACTIVITY_KICK_MS>0?MODE.INACTIVITY_KICK_MS:(a.kind==="public"?MODE.PUBLIC_INACTIVITY_KICK_MS:MODE.LOCAL_INACTIVITY_KICK_MS);for(const [slot,c] of [...a.players]){const q=a.world.players[slot].body.getPosition();if(c.inactivityPhase!==a.phase){c.inactivityPhase=a.phase;c.lastMovementAt=n;c.lastMovementX=q.x;c.lastMovementY=q.y;}if(Math.hypot(q.x-(c.lastMovementX??q.x),q.y-(c.lastMovementY??q.y))>=.08){c.lastMovementAt=n;c.lastMovementX=q.x;c.lastMovementY=q.y;}if(inactivityMs>0&&a.phase==="playing"&&n-c.lastMovementAt>=inactivityMs){send(c,{t:"returnHome",code:"inactivity",reason:"You have been kicked out for inactivity."});cleanup(c,{reconnect:false,notice:`${c.name} was kicked for inactivity`});c.socket.end();}}if(a.randomEventEligible&&!a.randomEventPlayed&&a.phase==="playing"&&n>=a.randomEventAt)playRandomEvent(a);if(!a.players.size&&!a.spectators.size&&n-a.lastUsed>30000){arenas.delete(a.id);if(a.party)parties.delete(a.party);}}for(const [id,r] of reconnects)if(r.expires<n)reconnects.delete(id);},4);
const messageBeforeExtendedChat=message;
message=function(c,m){if(m?.t!=="chat")return messageBeforeExtendedChat(c,m);c.last=now();const a=c.arena;if(!a)return;const text=String(m.text||"").trim().slice(0,540),team=!!m.team&&c.role==="player";if(text){const event={t:"chat",slot:c.slot,name:c.name,spectator:c.role!=="player",team,text};team?broadcastTeam(a,c.slot%2,event):broadcast(a,event);}};
server.listen(PORT,HOST,()=>console.log(`NitroClash local 11v11 listening on ws://${HOST}:${PORT}`));
export function closeServer(){clearInterval(physicsTimer);return new Promise(r=>server.close(r));}
